begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.courses(id,owner_id,title) values
 ('96000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','Analysis test');
set local role authenticated;
set local request.jwt.claims = '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}';
select public.prepare_file_upload('96000000-0000-0000-0000-000000000001','96000000-0000-0000-0000-000000000010','termine.txt','text/plain',100);
select throws_ok($$select * from public.material_analyses$$,'42501',null,'Analysis state cannot be read directly');
select throws_ok($$select * from public.material_analysis_decisions$$,'42501',null,'Receipts cannot be read directly');
select throws_ok($$select public.read_material_analysis(auth.uid(),gen_random_uuid())$$,'42501',null,'Clients cannot bypass Edge authentication');
select throws_ok($$select public.begin_material_analysis(auth.uid(),gen_random_uuid(),gen_random_uuid(),'{}')$$,'42501',null,'Clients cannot reserve with a forged owner');
select throws_ok($$select public.finish_material_analysis(auth.uid(),gen_random_uuid(),gen_random_uuid(),'[]','[]')$$,'42501',null,'Clients cannot forge results');
select throws_ok($$select public.decide_material_analysis(auth.uid(),gen_random_uuid(),'x','accept','{}')$$,'42501',null,'Clients cannot forge decisions');
reset role;
select public.complete_file_upload(id,'11111111-1111-1111-1111-111111111111') from public.files where course_id='96000000-0000-0000-0000-000000000001';
create temporary table target as select d.id,d.material_id from public.source_documents d join public.materials m on m.id=d.material_id where m.course_id='96000000-0000-0000-0000-000000000001';
create temporary table job(payload jsonb);
create temporary table result_event(id uuid);
create temporary table confirmation as select '{"title":"Mathematikprüfung","description":"Lineare Funktionen. Geodreieck mitbringen.","kind":"exam","starts_at":"2026-11-12T09:00:00+01:00","ends_at":null,"all_day":false}'::jsonb as value;
create temporary table suggestions as select '[{"id":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","type":"calendar_entry","title":"Mathematikprüfung","description":"Lineare Funktionen. Geodreieck mitbringen.","source":{"page":1,"quote":"Prüfung am 12. November 2026"},"review":{"required":false,"issues":[]},"data":{"kind":"event","date":"2026-11-12","time":"09:00:00","end_date":null,"end_time":null,"timezone":"Europe/Berlin","location":null,"submission_channel":null}}]'::jsonb as value;
select throws_ok($$select public.begin_material_analysis('22222222-2222-2222-2222-222222222222',gen_random_uuid(),(select material_id from target),'{}')$$,'P0001','TARGET_NOT_FOUND','Foreign material hidden');
select throws_ok($$select public.begin_material_analysis('11111111-1111-1111-1111-111111111111',gen_random_uuid(),(select material_id from target),'{}')$$,'P0001','SOURCES_NOT_READY','Unprocessed document rejected');
update public.source_documents set processing_status='ready',completed_at=now(),extracted_text='Prüfung am 12. November 2026',pages='[{"page":1,"text":"Prüfung am 12. November 2026"}]' where id=(select id from target);
insert into job select public.begin_material_analysis('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000020',(select material_id from target),'{}');
select is((select payload->>'run' from job),'true','First request reserves exactly one call');
select is(public.begin_material_analysis('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000020',(select material_id from target),'{}')->>'run','false','Concurrent retry does not start another call');
select throws_ok($$select public.begin_material_analysis('11111111-1111-1111-1111-111111111111','96000000-0000-0000-0000-000000000020',(select material_id from target),'{"timezone":"UTC"}')$$,'P0001','REQUEST_CONFLICT','Changed retry payload rejected');
select throws_ok($$select public.begin_material_analysis('11111111-1111-1111-1111-111111111111',gen_random_uuid(),(select material_id from target),'{}')$$,'P0001','ANALYSIS_RATE_LIMITED','Concurrent requests bounded per owner');
select throws_ok($$select public.finish_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),gen_random_uuid(),'[]','[]')$$,'P0001','ANALYSIS_EXPIRED','Wrong lease fenced');
select is(public.finish_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),(select (payload->>'lease_token')::uuid from job),(select value from suggestions),'[]')->>'status','completed','Valid result published');
select is((select count(*)::int from public.calendar_events where course_id='96000000-0000-0000-0000-000000000001'),0,'Analysis never creates calendar entries automatically');
select throws_ok($$select public.read_material_analysis('22222222-2222-2222-2222-222222222222',(select (payload->>'analysis_id')::uuid from job))$$,'P0001','ANALYSIS_NOT_FOUND','Foreign analysis hidden');
select throws_ok($$select public.decide_material_analysis('22222222-2222-2222-2222-222222222222',(select (payload->>'analysis_id')::uuid from job),repeat('a',64),'accept',(select value from confirmation))$$,'P0001','ANALYSIS_NOT_FOUND','Foreign import rejected');
select throws_ok($$select public.decide_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),'unknown','accept',(select value from confirmation))$$,'P0001','ITEM_NOT_FOUND','Unknown item rejected');
select throws_ok($$select public.decide_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),repeat('a',64),'accept',null)$$,'P0001','INVALID_REQUEST','Explicit calendar confirmation required');
insert into result_event select (public.decide_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),repeat('a',64),'accept',(select value from confirmation))->>'calendar_event_id')::uuid;
select is((select description from public.calendar_events where id=(select id from result_event)),'Lineare Funktionen. Geodreieck mitbringen.','Term description preserved in calendar');
select is((select starts_at from public.calendar_events where id=(select id from result_event)),'2026-11-12T08:00:00Z'::timestamptz,'Explicit timezone offset respected');
select is((public.decide_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),repeat('a',64),'accept',(select value from confirmation))->>'calendar_event_id')::uuid,(select id from result_event),'Retry returns same calendar event');
select is((select count(*)::int from public.calendar_events where course_id='96000000-0000-0000-0000-000000000001'),1,'Retry creates no duplicate');
select throws_ok($$select public.decide_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),repeat('a',64),'dismiss')$$,'P0001','DECISION_CONFLICT','A decision is not silently reversed');
select is(jsonb_array_length(public.read_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job))->'decisions'),1,'Result includes import receipt');
delete from public.calendar_events where id=(select id from result_event);
select is((public.decide_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),repeat('a',64),'accept',(select value from confirmation))->>'calendar_event_id')::uuid,(select id from result_event),'Receipt survives deletion');
select is((select count(*)::int from public.calendar_events where course_id='96000000-0000-0000-0000-000000000001'),0,'Deleted event is not recreated by retry');
-- A fresh analysis of the same item still uses the receipt.
delete from job;
insert into job select public.begin_material_analysis('11111111-1111-1111-1111-111111111111',gen_random_uuid(),(select material_id from target),'{}');
select public.finish_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),(select (payload->>'lease_token')::uuid from job),(select value from suggestions),'[]');
select is((public.decide_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),repeat('a',64),'accept',(select value from confirmation))->>'calendar_event_id')::uuid,(select id from result_event),'Reanalysis deduplicates previously accepted item');
delete from job;
insert into job select public.begin_material_analysis('11111111-1111-1111-1111-111111111111',gen_random_uuid(),(select material_id from target),'{}');
update public.source_documents set extracted_text='Geänderter Inhalt' where id=(select id from target);
select is(public.finish_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job),(select (payload->>'lease_token')::uuid from job),'[]','[]')->>'error_code','SOURCE_CHANGED','Changing sources invalidate in-flight output');
delete from job;
insert into job select public.begin_material_analysis('11111111-1111-1111-1111-111111111111',gen_random_uuid(),(select material_id from target),'{}');
update public.material_analyses set lease_until=now()-interval '1 second' where id=(select (payload->>'analysis_id')::uuid from job);
select is(public.read_material_analysis('11111111-1111-1111-1111-111111111111',(select (payload->>'analysis_id')::uuid from job))->>'error_code','ANALYSIS_TIMEOUT','Abandoned request becomes failed on read');
update public.source_documents set extracted_text=repeat('x',60001) where id=(select id from target);
select throws_ok($$select public.begin_material_analysis('11111111-1111-1111-1111-111111111111',gen_random_uuid(),(select material_id from target),'{}')$$,'P0001','SOURCE_LIMIT_EXCEEDED','Oversized sources rejected without silent truncation');
set local role anon;
select throws_ok($$select * from public.material_analyses$$,'42501',null,'Anonymous state access denied');
select throws_ok($$select public.read_material_analysis(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Anonymous RPC denied');
reset role;
delete from public.courses where id='96000000-0000-0000-0000-000000000001';
select is((select count(*)::int from public.material_analyses where material_id=(select material_id from target)),0,'Material deletion cascades to analyses');
select is((select count(*)::int from public.material_analysis_decisions where material_id=(select material_id from target)),0,'Material deletion cascades to decisions');
select * from finish();
rollback;
